    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row_start = by * TILE_DIM;
    int col_start = bx * TILE_DIM;

    float C_values[THREAD_WORK] = {0.0f};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles into shared memory
        #pragma unroll
        for (int i = 0; i < THREAD_WORK; ++i) {
            int row = row_start + ty + i * (TILE_DIM / THREAD_WORK);
            int col_a = t * TILE_DIM + tx;
            if (row < N && col_a < N) {
                As[ty + i * (TILE_DIM/THREAD_WORK)][tx] = A[row * N + col_a];
            } else {
                As[ty + i * (TILE_DIM/THREAD_WORK)][tx] = 0.0f;
            }
        }

        int row_b = t * TILE_DIM + ty;
        #pragma unroll
        for (int i = 0; i < THREAD_WORK; ++i) {
            int col = col_start + tx + i * (TILE_DIM/THREAD_WORK);
            if(row_b < N && col < N) {
                Bs[ty][tx + i * (TILE_DIM/THREAD_WORK)] = B[row_b * N + col];
            } else {
