import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

        cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define THREADS_X 16
#define THREADS_Y 16
#define C_TILE_X 4
#define C_TILE_Y 4

__global__ void matmul_kernel_fixed(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row_base = by * TILE_DIM;
    int col_base = bx * TILE_DIM;

    float c[C_TILE_Y][C_TILE_X] = {{0.0f}};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load A tile
        for (int i = 0; i < C_TILE_Y; ++i) {
            int row = row_base + ty + i * THREADS_Y;
            int col = t * TILE_DIM + tx;
            if (row < N && col < N) {
                As[ty + i * THREADS_Y][tx] = A[row * N + col];
            } else {
                As[ty + i * THREADS_Y][tx] = 0.0f;
            }
        }

        // Load B tile
        for (int i = 0; i < C_TILE_X; ++i) {
            int row = t * TILE_DIM + ty;
            int col = col_base + tx + i * THREADS_X;
            if (row < N && col < N) {
                Bs[ty][tx + i * THREADS_X] = B[row * N + col];
            } else {
                Bs[ty][tx + i * THREADS_X] = 0.0f;
            }
        }
        __syncthreads();

        // Compute
        for (int k = 0; k < TILE_DIM; ++k) {
            for (int i = 0; i < C_TILE_Y; ++i) {
                for (int j = 0; j < C_TILE_X; ++j) {
                    c[i][j] += As[ty + i * THREADS_Y][k] * Bs[k][tx + j * THREADS_X];
                }
            }
        }
        __syncthreads();
    }

    // Write to C
    for (int i = 0; i < C_TILE_Y; ++i) {
        for (int j = 0; j < C_TILE_X; ++j) {
            int row = row_base + ty + i * THREADS_Y;
            int col = col_base + tx + j * THREADS_X;
            if (row < N && col < N) {
                C[row * N + col] = c[i][j];
            }
        }
    }
}


